export const nestedCatalogFeaturedInsetBefore = "[data-stack-kind=\"catalog.home\"] [data-catalog-home] > [data-place-stack=\"featured\"] { padding-inline:1rem; }\n";

/** The frozen sources as svelteBrowser overrides (absolute path → source), for a "before" rendering. */
export const mediaCompositionsBeforeOverrides: Readonly<Record<string, string>> = Object.fromEntries(Object.entries(mediaCompositionsBefore)
  .map(([path, source]) => [resolve(import.meta.dirname, "../..", path), source]));
